/* Numbered reading units live on the parent title; catalogs rarely supply chapter names. */
(function(root){
 const units=['Chapters','Volumes','Pages'];
 function update(previous,unit,count,selected,done,final){if(!units.includes(unit)||!Number.isInteger(count)||count<1||count>100000)throw Error('Enter a whole-number count from 1 to 100000.');const next=structuredClone(previous||{units:{}}),old=next.units[unit]||{completed:[]},set=new Set(old.completed);for(const n of selected){if(!Number.isInteger(n)||n<1||n>count)throw Error('Invalid reading unit.');done?set.add(n):set.delete(n);}next.units[unit]={count,final:!!final,completed:[...set].filter(n=>n<=count).sort((a,b)=>a-b)};next.active=unit;return next;}
 function totals(state,unit){const row=state?.units?.[unit];return {completed:row?.completed.length||0,total:row?.count||null};}
 if(typeof module==='object')module.exports={update,totals};if(typeof document==='undefined')return;
 function bind(container){const hero=container.querySelector('.media-hero'),media=hero&&FolioMediaInfo.forElement(hero);if(!media||!['book','manga'].includes(media.kind)||container.querySelector('.reading-checklist'))return;
  const entry=()=>items.find(x=>x.metadata&&FolioIdentity.same(x.metadata,media));const section=document.createElement('section');section.className='live-detail-section media-collections reading-checklist';section.innerHTML='<h3>Reading progress</h3><p>Track numbered chapters, volumes or pages on this title. Counts are independent; choose which one controls overall progress. Enter counts for your edition when the catalog does not supply them.</p><div class="reading-controls"><label>Track by<select aria-label="Reading progress unit">'+units.map(u=>`<option>${u}</option>`).join('')+'</select></label><label>Total or available count<input aria-label="Reading unit count" type="number" min="1" max="100000" step="1"></label><label><input type="checkbox" aria-label="Complete title when all units are finished">This is the full total; complete the title when all are finished</label><button type="button" data-reading-setup>Save count</button></div><p class="reading-message" role="status"></p><div class="reading-summary series-progress-summary"></div><div class="reading-actions"><label>Mark through<input aria-label="Mark reading progress through" type="number" min="1" step="1"></label><button type="button" data-reading-through>Mark through completed</button><button type="button" data-reading-all>Mark all completed</button><button type="button" data-reading-clear>Clear this checklist</button><button type="button" data-reading-manual>Use manual progress</button></div><div class="reading-list"></div><div class="reading-pages"><button type="button" data-reading-prev>Previous units</button><span></span><button type="button" data-reading-next>Next units</button></div>';
  (container.querySelector('.media-overview')||hero).after(section);const select=section.querySelector('select'),count=section.querySelector('[aria-label="Reading unit count"]'),final=section.querySelector('[type=checkbox]'),message=section.querySelector('.reading-message');let page=0;
  select.value=entry()?.readingProgress?.active||(media.kind==='book'?'Pages':'Chapters');
  function settings(){const row=entry()?.readingProgress?.units?.[select.value];const supplied=Number(media.facts?.[select.value]);count.value=row?.count||(Number.isInteger(supplied)&&supplied>0?supplied:'');final.checked=row?.final??false;page=0;draw();}
  function draw(){const focus=document.activeElement?.dataset?.readingUnit;const x=entry(),row=x?.readingProgress?.units?.[select.value],p=totals(x?.readingProgress,select.value),done=new Set(row?.completed||[]),start=page*50+1,end=Math.min(row?.count||0,start+49);section.querySelector('.reading-summary').innerHTML=x?`<strong>${p.completed}${p.total?' / '+p.total:''} ${esc(select.value.toLowerCase())} completed</strong>${p.total?`<progress value="${p.completed}" max="${p.total}" aria-label="Reading progress"></progress>`:''}`:'Add the full title to your library to save reading progress.';section.querySelector('.reading-list').innerHTML=Array.from({length:Math.max(0,end-start+1)},(_,i)=>{const n=start+i;return `<label><input type="checkbox" data-reading-unit="${n}" ${done.has(n)?'checked':''}>${esc(select.value.slice(0,-1))} ${n}</label>`;}).join('');section.querySelectorAll('[data-reading-unit]').forEach(el=>el.onchange=()=>save([Number(el.dataset.readingUnit)],el.checked));if(focus)section.querySelector(`[data-reading-unit="${focus}"]`)?.focus({preventScroll:true});section.querySelector('[data-reading-prev]').disabled=page===0;section.querySelector('[data-reading-next]').disabled=!row||end>=row.count;section.querySelector('.reading-pages span').textContent=row?`${start}–${end} of ${row.count}`:'';section.querySelectorAll('.reading-actions button').forEach(b=>b.disabled=!row);section.querySelector('[data-reading-setup]').disabled=!x;
   const dialog=section.closest('dialog');if(x&&dialog?.id==='detail'){for(const [id,val] of [['episodes-done',x.episodeProgress?.completed||0],['episodes-total',x.episodeProgress?.total||''],['progress-unit',x.progressUnit]]){const el=dialog.querySelector('#'+id);if(el){if(x.readingProgress){if(id==='progress-unit'&&![...el.options].some(o=>o.value===val))el.add(new Option(val,val));el.value=val;}el.disabled=!!x.readingProgress;}}const b=dialog.querySelector('#episode-form button[type=submit]');if(b)b.disabled=!!x.readingProgress;const note=dialog.querySelector('#episode-form .disclaimer');if(note)note.textContent=x.readingProgress?'The reading checklist controls overall progress.':'Set progress here or use the reading checklist.';const bar=dialog.querySelector('.activity-section progress');if(bar&&x.episodeProgress?.total){bar.max=x.episodeProgress.total;bar.value=x.episodeProgress.completed;}const caption=dialog.querySelector('.activity-section progress + .muted');if(caption&&x.readingProgress)caption.textContent=`${x.episodeProgress.completed} of ${x.episodeProgress.total} completed`;}
  }
  function save(selected,done){try{const latest=JSON.parse(localStorage.getItem('folio-library-v1')||'null');if(Array.isArray(latest))items=root.FolioLibraryPatch?root.FolioLibraryPatch.entries(latest):latest;}catch{}const x=entry();if(!x)return;const before=structuredClone(x);try{if(!x.readingProgress&&x.episodeProgress?.completed&&!confirm('Use a reading checklist instead of your manual count? Your previous count will be retained.')){draw();return;}const next=update(x.readingProgress,select.value,Number(count.value),selected,done,final.checked);if(!x.readingProgress)x.previousManualReadingProgress=structuredClone(x.episodeProgress||{});x.readingProgress=next;x.progressUnit=select.value;x.episodeProgress=totals(next,select.value);const p=x.episodeProgress;if(final.checked&&p.completed===p.total)x.status='Completed';else if(p.completed||x.status==='Completed')x.status='In progress';delete x.completionPreviousStatus;if(!persist())throw Error('Progress could not be saved.');render();message.textContent='Reading progress saved.';draw();section.closest('dialog').querySelectorAll('[data-status-id]').forEach(el=>{if(el.dataset.statusId===x.id)el.value=x.status;});}catch(e){Object.keys(x).forEach(k=>delete x[k]);Object.assign(x,before);message.textContent=e.message;draw();}}
  section.querySelector('[data-reading-manual]').onclick=()=>{const x=entry();if(!x)return;const old=x.readingProgress;delete x.readingProgress;if(!persist())x.readingProgress=old;draw();};select.onchange=settings;section.querySelector('[data-reading-setup]').onclick=()=>save([],true);section.querySelector('[data-reading-through]').onclick=()=>{const n=Number(section.querySelector('[aria-label="Mark reading progress through"]').value);if(!Number.isInteger(n)||n<1||n>100000||n>Number(count.value)){message.textContent='Choose a unit within your count.';return;}save(Array.from({length:n},(_,i)=>i+1),true);};section.querySelector('[data-reading-all]').onclick=()=>{const n=Number(count.value);if(!Number.isInteger(n)||n<1||n>100000){message.textContent='Enter a count from 1 to 100000.';return;}save(Array.from({length:n},(_,i)=>i+1),true);};section.querySelector('[data-reading-clear]').onclick=()=>save(entry()?.readingProgress?.units?.[select.value]?.completed||[],false);section.querySelector('[data-reading-prev]').onclick=()=>{page--;draw();};section.querySelector('[data-reading-next]').onclick=()=>{page++;draw();};function onSave(){if(!section.isConnected){document.removeEventListener('submit',onSave);return;}queueMicrotask(draw);}document.addEventListener('submit',onSave);settings();
 }
 root.FolioReadingProgress={bind};
})(globalThis);
